		boolean warikire = false;

		for(int i=2; i<=Math.sqrt(n); i++){
			if( n%i == 0 ){
				a = i;
				warikire = true;
			}
		}

		if(warikire){
			if( keta((long)Math.sqrt(n)) > keta(a) ){
				System.out.println( keta((long)Math.sqrt(n)) );
			}else{
				System.out.println( keta(a) );
			}
		}else{
			System.out.println( keta(n) );
		}
		return;
	}

	public static int keta( long a ){
		int ans = 1;
		while( a/10 != 0 ){
			a /= 10;
			ans++;
		}
		return ans;
	}
}

