		int max = 1;
		for (int i = 2; i < MAX; ++i) {
			int pow = i;
			for (int j = 2; j < 9; ++j) {
				pow *= i;
				if (X < pow) {
					break;
				}
				if (max < pow) {
					max = pow;
				}
			}
		}
		return max;
	}


