	for(int j = 0;j < N;j++){
	    B[j] = sc.nextInt();
	}
	for(int j = 0;j < N;j++){
	    if(binarySearch(A,B[j])){
		count++;
	    }
	}
	System.out.println(count);
    }
 //     public static boolean linearSearch(int[] A,int key){
//     	int i = 0;
//     	for(i = 0;i < A.length;i++){
//     	    if(A[i] == key){
//     		return true;
//     	    }
//     	}
//     	return false;
//     }
// }
    public static boolean binarySearch(int[] A,int key){
    	int left = 0;
    	int right = A.length;
    	int mid = 0;
    	while(left < right){
    	    mid = (left + right) / 2;

    	    if(A[mid] == key){
    		return true;
    	    }else if(key < A[mid]){
    		right = mid;
    	    }else{
    		left = mid + 1;
    	    }
    	}
    	return false;
    }
}

