		Scanner scanner = new Scanner(System.in);
		int[][] nums = new int[4][4];
		for (int rIdx = 1; rIdx <= 3; rIdx++) {
			String[] inputs = scanner.nextLine().split(" ");
			for (int cIdx = 1; cIdx <=3; cIdx++) nums[rIdx][cIdx] = Integer.parseInt(inputs[cIdx - 1]);
		}

