    static class Solver {
        int N;
        // int[] A;

        // write your code
        void solve(InputReader in, PrintWriter out) {
            N = in.nextInt();
            int ans = 0;
            for (int i = 1; i <= N; i += 2) {
                int cnt = 0;
                for (int j = 1; j <= i; j++) {
                    if (i % j == 0) {
                        cnt++;
                    }
                }
                if (cnt == 8) {
                    ans++;
                }
            }
            out.println(ans);
        }

        void debug(Object... os) {
            System.err.println(Arrays.deepToString(os));
        }
    }

