public static class Solution{
    public static void main(String[] ar){
        int i,j,N,tmp,cnt;
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();

		int [] A = new int [N];

		for(i=0; i<N; i++){
			A[i] =sc.nextInt();
		}
		cnt =0;
