            int n = sc.nextInt();
            // nを27で何回割れる？
            List<Integer> list = new ArrayList<>();
            while(true){
                int ans = n / 27;
                int amr = n % 27;
                if(ans == 0){
                    if(amr != 0){
                        list.add(amr);
                    }
                    break;
                }else{
                    list.add(ans);
                    n = amr;
                }
            }
            StringBuilder sb = new StringBuilder();
            for(Integer i : list){
                sb.append((char)(i+96));
            }
