		long n = v.nextLong();
		int k = v.nextInt();
		System.out.println(calc(n,k));

	}
	public static long calc(long n, int k) {
		if (n < k) {
			return n;
		}

		while(n>0) {
			n = n - k;
		}
		if(n<0) {
			n = -n;
		}
		return n;
	}
}

