        }


    }

    static int regex(String str, String target){
        int count = 0;
        String[] s = str.split("");
        for(int i = 0; i < str.length(); i++){
            if(s[i].equals("A")) {
                if(i >= str.length()-1) continue;
                count += s[i + 1].equals("C") ? 1 : 0;
                i++;
            }
        }
        return count;
    }
}

