    static class AFiftyFifty {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            String s = in.next();
            int[] hash = new int[26];
            int count = 0;
            for (int i = 0; i < s.length(); i++) {
                int c = s.charAt(i) - 'A';
