    int cnt = 0;
    while (flipped != 0) {
      flipped = flipped % numPop(flipped);
      cnt++;
    }
    return cnt;
  }

  public static int numPop(int num) {
    int cnt = 0;
    while (num != 0) {
      cnt += (num & 1);
      num = num >> 1;
    }
    return cnt;
  }

