			h[i] = Integer.parseInt(s_in[i]);
		}

		double[] tempe = new double[N];
		for(int i=0;i<N;i++) {
			tempe[i] = (double)T - h[i]*0.006;
		}

		int nearest_h = -1;
		double nearest_dist = 100000;
		for(int i=0;i<N;i++) {
