                monster[i + 1] -= (hero[i] - monster[i]);
                count += hero[i];
            } else if (monster[i] + monster[i + 1] < hero[i]) {
                monster[i + 1] = 0;
                count += monster[i] + monster[i + 1];
            }
        }
