import java.util.Scanner;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        for(int i = 0; i < N; i++){
            A[i] = sc.nextInt();
        }
        int count = SelectionSort(A, N);
        for(int i = 0; i < N; i++){
            if(i != N - 1){
                System.out.print(A[i] + " ");
            }else{
                System.out.print(A[i]);
            }
        }
        System.out.println("");
        System.out.println(count);
    }

    public static int SelectionSort(int[] a, int n){
        int c = 0;
        for(int i = 0; i <= n - 1; i++){
            int minj = i;
            for(int j = i; j <= n - 1; j++){
                if(a[j] < a[minj]){
                    minj = j;
                }
            }
            if(i != minj){
                int x = a[i];
                a[i] = a[minj];
                a[minj] = x;
                c++;
            }
        }
        return c;
    }
}

import java.util.*;
import java.lang.Math;

class Main {

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int numStones = scanner.nextInt();

    if (numStones < 2 || numStones > 100000) {
      System.out.println("0");
      return;
    }

    ArrayList<Integer> heights = new ArrayList<>();
    for (int i = 0; i < numStones; i++) {
      heights.add(i, scanner.nextInt());
    }
    int cost = calcCost(numStones, heights);

    System.out.println(cost);
  }

  public static int calcCost(int N, ArrayList<Integer> heights) {
    ArrayList<Integer> dp = new ArrayList<>();

    dp.add(0, 0);
    dp.add(1, Math.abs(heights.get(1)-heights.get(0)));

    if (N == 2) {
      return dp.get(1);
    }

    int cost;
    int firstJump;
    int secondJump;
    for (int i = 2; i < N; i++) {
      firstJump = Math.abs(heights.get(i)-heights.get(i-1));
      secondJump = Math.abs(heights.get(i)-heights.get(i-2));
      cost = Math.min(firstJump + dp.get(i-1), secondJump + dp.get(i-2));
      dp.add(i, cost);
    }
    return dp.get(N-1);
  }
}

