		while(i<n) {
			i++;
			for(int k=i+1;k<n;k++) {
				if(!pp[i].equals(pp[k])) {
					ans+= ((k-1)-i)*(k-i)/2;
					i=k-1;
					break;
				}
				if(k==n-1) {
					ans+= (k-i+1)*(k-i)/2;
					break;
				}
			}

		}
