            curLayer *= 26;
            if (curLayer >= n) break;
            n -= curLayer;

        }


        n -- ;

        StringBuilder res = new StringBuilder();

        for (int i = 0; i < layers; i ++ ) { 
            res.append((char)('a' + n % 26));
            n /= 26;
        }
