			for(j=0;j<N-(i+1);j++){
				if(A[j] > A[j+1]){
					tmp  = A[j];
					A[j] = A[j+1];
					A[j+1] = tmp;
					cnt++;
				}
			}
		}

		for(int r=0; r<N; r++){
			System.out.print(A[r]+" ");
		}
		System.out.println("\r\n"+cnt);

	}

