				double sum = 0;
				for(int k = 0; k < D; k++) {
					double tmp = Math.abs((double)(B[i][k] - B[j][k]));
					sum += Math.pow(tmp, 2);
				}
				double num = Math.sqrt(sum);
				if(num - (int)num == 0) {
					ans++;
				}
			}
		}

		System.out.println(ans);
		scan.close();
	}

}

