	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner s=new Scanner(System.in);
		int K=s.nextInt();
		int S=s.nextInt();
		int count=0;
		int i=0,j=0,k=0;

		for(i=0;i<=K;i++){
			if(i==S){
				count++;
				continue;
			}
			for(j=0;j<=K;j++){
				if(i==0&&j==0){
					count++;
					continue;
				}
				if(i+j==S){
					count++;
					continue;
				}
				for(k=0;k<=K;k++){
					if(i+j+k==S)count++;
					else continue;
				}
			}
		}

		System.out.print(count);
	}

}

