    void solve() {
        int i,j;
        int n=i(), k=i();
        int a[]=new int[n];
        int dp[][]=new int[n][k+1];
        for(i=0;i<n;i++)
            a[i]=i();
        for(i=0;i<n;i++)
            dp[i][0]=Integer.MAX_VALUE;
        for(i=1;i<=k;i++)
            dp[1][i]=Math.abs(a[1]-a[0]);
        for(i=2;i<n;i++) {
            if(i<=k) {
                for(j=1;j<=i;j++)
                    dp[i][j]=Math.min(dp[i][j-1], dp[i-j][k] + Math.abs(a[i-j]-a[i]));
                for(j=i+1;j<=k;j++)
                    dp[i][j]=dp[i][j-1];
            }
            else {
                for(j=1;j<=k;j++)
                    dp[i][j]=Math.min(dp[i][j-1], dp[i-j][k] + Math.abs(a[i-j]-a[i]));
            }
        }
        System.out.println(dp[n-1][k]);
    }
