        int b = in.nextInt();
        int timer = 0;

        for (int i = 0; i < a; i++) {
            name.add(in.next());
            time.add(in.nextInt());
        }
        while (name.size() != 0) {
            if (time.peek() - b > 0) {
                name.add(name.poll());
                time.add(time.poll() - b);
                timer += b;
            } else {
                timer += time.poll();
                System.out.println(name.poll() + " " + timer);
            }
        }
    }
}

