						hasOtherCapital = true;
					}
				}
			}

			if(firstA == true && thirdC == true && cCount == 1 && hasOtherCapital == false){
				bw.write("AC");
				bw.flush();
			}else{
				bw.write("WA");
				bw.flush();
			}
		}else{
			bw.write("WA");
			bw.flush();
		}

		bw.close();
		br.close();
	}
