public class Main{

    public static int select(int A[],int N){
        int cnt=0;
        for(int i=0;i<N;i++){
            int minj=i;
            for(int j=i;j<N;j++){
                if(A[j]<A[minj]){
                    minj = j;
                }
            }
            if(minj!=i){
                int t=A[i];
                A[i]=A[minj];
                A[minj]=t;
                cnt++;
            }
        }
        return cnt;
    }
