            dp[i] = 1000000000;
        }

        dp[0] = 0;
        dp[1] = 0;

        for (int i = 2; i <= n; i++) {

            if (i == 2) dp[i] = dp[i-1] + Math.abs(heights[i-2] - heights[i - 1]);

            else {
                dp[i] = Math.min(dp[i-1] + Math.abs(heights[i-2] - heights[i - 1]),
                        dp[i-2] + Math.abs(heights[i-3] - heights[i - 1]));
            }
        }

        out.println(dp[n]);

        out.close();
    }
}

