					ans = n/i;
					break;
				}
			}

			//最小公倍数

			ax = bx = 1;

			while(true) {
				if(a * ax == b * bx) {
					break;
				}else if(a * ax > b * bx){
					bx++;
				}else if(a * ax < b * bx){
					ax++;
				}
			}
			System.out.println(ans + " " + a * ax);
		}

