    private static String totalMoves(int x[]) {
        int biggest = 0;
        int sum = 0;
        for(int i = 0; i < x.length; i++) {
            if(x[i] > biggest) {
                biggest = x[i];
            }
            sum = sum + x[i];
        }

        sum = sum - biggest;
        if(sum > biggest) {
            return "Yes";
        }

        return "No";
    }

