import java.util.Scanner;
import java.util.ArrayList;
import java.util.Collections;
class Main{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    ArrayList <Integer> li = new ArrayList <Integer>();
    ArrayList <Integer> liu = new ArrayList <Integer>();
    ArrayList <Integer> lir = new ArrayList <Integer>();
    int x = sc.nextInt();
    int n = sc.nextInt();
    for(int i=0;i<n;i++){
      int a = sc.nextInt();
      li.add(a);
    }
    Collections.sort(li);
    int l=0;
    int k=0;
    int m=0;
    if(li.size() == 0){
      System.out.println(x);
      System.exit(0);
    }
    liu.add(li.get(0) - 2);
    for(int i=0;i<n;i++){
      if(li.get(i)<x){
        liu.add(li.get(i));
      }else if(li.get(i)>x){
        lir.add(li.get(i));
      }else{
        l++;
      }
    }
    lir.add(li.get(n-1) + 2);
    int under = 0;
    int upper = 0;
    for(int i=1;i<liu.size()+1;i++){
        if(x-i>liu.get(liu.size()-i)){
          k++;
          under=x-i;
          break;
        }
      }
    if(k==0){
        under=liu.get(0)-1;
      }
      for(int i=1;i<lir.size()+1;i++){
        if(x+i<lir.get(i-1)){
          m++;
          upper=x+i;
          break;
        }
      }
      if(m==0){
        upper=liu.get(liu.size()-1)+1;
      }
    if(l==0){
      System.out.println(x);
    }else if(x-under<upper-x){
        System.out.println(under);
      }else if(x-under>upper-x){
        System.out.println(upper);
      }else{
        System.out.println(under);
      }

  }
}

import java.io.*;
import java.util.*;

public class Main {

    static long mod = (long) (1e9 + 7);

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        int total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (i != j) {
                    int ans = a[i] * a[j];
                    total += ans;
                }
            }
        }
        out.println(total);
        out.close();
    }

    static long[][] powMat(long[][] a, long pow) {
        if (pow == 1) {
            return a;
        } else {
            if (pow % 2 == 0) {
                return powMat(mul(a, a), pow / 2);
            } else {
                return mul(a, powMat(mul(a, a), pow / 2));
            }
        }
    }

    static long[][] mul(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    c[i][k] = (c[i][k] + (a[i][j] * b[j][k]) % mod) % mod;
                }
            }
        }
        return c;
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

