import java.io.*;

class Calc{
    public static int gcd(int a, int b, int c)  {
        int r;
        while (b > 0) {
            r = a % b;
            a = b;
            b = r;
        }
        while (c > 0) {
            r = a % c;
            a = c;
            c = r;
        }
        return a;
    }
}

