		Scanner scan = new Scanner(System.in);

		int[] charArr = new int[26];

		String str;
		while (!(str = scan.nextLine()).isEmpty()) {
			for (char c : str.toCharArray()) {
				if (c > 64 && c < 91) {
					charArr[c - 65]++;
				}
				if (c > 96 && c < 123) {
