			int n = Integer.parseInt(scan.nextLine());
			if (n == 0) {
				break;
			}
			String sTmp = scan.nextLine();
			int sum = 0;
			int[] s = new int[n];
 			for (int i = 0; i < n; i++) {
				s[i] = Integer.parseInt(sTmp.split(" ")[i]);
				sum += s[i];
			}
